    slug: "crm-im-recruiting-beziehungen-skalieren",
    title: "CRM im Recruiting: Wie Beratungen Beziehungen skalieren statt Daten pflegen",
    seoTitle: "CRM im Recruiting: Beziehungen skalieren | ShortSelect",
    date: "2025-12-23",
